package com.biocircular.compostaje.exception; import org.springframework.http.*; import org.springframework.web.bind.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(BusinessException.class) ResponseEntity<Map<String,String>> business(BusinessException e){return error(HttpStatus.UNPROCESSABLE_ENTITY,e.getMessage());} @ExceptionHandler(NoSuchElementException.class) ResponseEntity<Map<String,String>> missing(NoSuchElementException e){return error(HttpStatus.NOT_FOUND,e.getMessage());} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<Map<String,String>> validation(MethodArgumentNotValidException e){return error(HttpStatus.BAD_REQUEST,e.getBindingResult().getFieldErrors().getFirst().getDefaultMessage());} private ResponseEntity<Map<String,String>> error(HttpStatus s,String message){return ResponseEntity.status(s).body(Map.of("error",message));} }
